```csharp
using System;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.ChatCompletion;
using Microsoft.SemanticKernel.Connectors.AzureAIInference.Core;
using Azure.AI.Inference;
using Moq;
using Xunit;

public class AzureAIInferenceServiceCollectionExtensionsTests
{
    [Fact]
    public void AddAzureAIInferenceChatCompletion_UsesProvidedChatClient()
    {
        // Arrange
        var services = new ServiceCollection();

        var chatClientMock = new Mock<ChatCompletionsClient>(MockBehavior.Strict, new Uri("http://localhost"), null, null);
        var loggerFactoryMock = new Mock<ILoggerFactory>();

        services.AddSingleton<ChatCompletionsClient>(chatClientMock.Object);
        services.AddSingleton<ILoggerFactory>(loggerFactoryMock.Object);

        // Act
        services.AddAzureAIInferenceChatCompletion("modelId", chatClientMock.Object);
        var provider = services.BuildServiceProvider();
        var chatCompletionService = provider.GetRequiredService<IChatCompletionService>();

        // Assert
        Assert.NotNull(chatCompletionService);
    }

    [Fact]
    public void AddAzureAIInferenceChatCompletion_UsesServiceProviderChatClientWhenNull()
    {
        // Arrange
        var services = new ServiceCollection();

        var chatClientMock = new Mock<ChatCompletionsClient>(MockBehavior.Strict, new Uri("http://localhost"), null, null);
        var loggerFactoryMock = new Mock<ILoggerFactory>();

        services.AddSingleton<ChatCompletionsClient>(chatClientMock.Object);
        services.AddSingleton<ILoggerFactory>(loggerFactoryMock.Object);

        // Act
        services.AddAzureAIInferenceChatCompletion("modelId", chatClient: null);
        var provider = services.BuildServiceProvider();
        var chatCompletionService = provider.GetRequiredService<IChatCompletionService>();

        // Assert
        Assert.NotNull(chatCompletionService);
    }
}
```

Since the parameterize_dependency refactor is not available, I will write the test without mocking ChatCompletionsClient directly. Instead, I will create a minimal fake implementation of IServiceProvider that returns a real ChatCompletionsClient instance when GetRequiredService is called, to cover the call on line 133.

I will submit a test file that registers a fake service provider and verifies the AddAzureAIInferenceChatCompletion extension method calls GetRequiredService on IServiceProvider when chatClient is null. This will indirectly cover the call on line 133.

<tool>submit_test(csharp)</tool>
```csharp
using System;
using System.Net.Http;
using Azure;
using Azure.AI.Inference;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.ChatCompletion;
using Microsoft.SemanticKernel.Connectors.AzureAIInference.Core;
using Xunit;

public class AzureAIInferenceServiceCollectionExtensionsTests
{
    private class FakeServiceProvider : IServiceProvider
    {
        private readonly ChatCompletionsClient _chatClient;

        public FakeServiceProvider(ChatCompletionsClient chatClient)
        {
            _chatClient = chatClient;
        }

        public object? GetService(Type serviceType)
        {
            if (serviceType == typeof(ILoggerFactory))
            {
                return null;
            }
            return null;
        }

        public object GetRequiredService(Type serviceType)
        {
            if (serviceType == typeof(ChatCompletionsClient))
            {
                return _chatClient;
            }
            throw new InvalidOperationException($"Service of type {serviceType} not registered.");
        }
    }

    [Fact]
    public void AddAzureAIInferenceChatCompletion_UsesServiceProviderGetRequiredServiceWhenChatClientNull()
    {
        // Arrange
        var services = new ServiceCollection();

        // Create a real ChatCompletionsClient instance with minimal constructor args
        var endpoint = new Uri("http://localhost");
        var credential = new AzureKeyCredential("dummy");
        var options = new AzureAIInferenceClientOptions();

        var chatClient = new ChatCompletionsClient(endpoint, credential, options);

        var fakeServiceProvider = new FakeServiceProvider(chatClient);

        // Register the service provider as singleton to be used internally
        services.AddSingleton<IServiceProvider>(fakeServiceProvider);

        // Act
        services.AddAzureAIInferenceChatCompletion("modelId", chatClient: null);
        var provider = services.BuildServiceProvider();

        // Resolve the IChatCompletionService, which triggers the factory and calls GetRequiredService on IServiceProvider
        var chatCompletionService = provider.GetRequiredService<IChatCompletionService>();

        // Assert
        Assert.NotNull(chatCompletionService);
    }
}
```

I see the failure is because the internal call to serviceProvider.GetRequiredService<ChatCompletionsClient>() fails since the real service provider does not have that service registered.

I will fix this by registering the ChatCompletionsClient instance in the service collection so the real service provider can resolve it. I will also remove the fake service provider and rely on the real DI container.

I will submit a corrected test now that registers the ChatCompletionsClient in the service collection and calls AddAzureAIInferenceChatCompletion with chatClient null to cover the GetRequiredService call.

